def merge_tool_results(calls, results):
    """One dict per call, in call order.

    A call whose id has a result becomes {'id': id, 'status': 'done', 'content': content}
    (content defaults to '' when the result carries none); otherwise {'id': id, 'status': 'pending'}.
    The last result for an id wins; results with an id no call has are ignored.
    Duplicate call ids are rejected. Neither input is mutated."""
    seen = set()
    for call in calls:
        cid = call["id"]
        if cid in seen:
            raise ValueError(f"duplicate call id: {cid!r}")
        seen.add(cid)
    last = {}
    for result in results:
        last[result["id"]] = result
    out = []
    for call in calls:
        cid = call["id"]
        result = last.get(cid)
        if result is None:
            out.append({"id": cid, "status": "pending"})
        else:
            out.append({"id": cid, "status": "done", "content": result.get("content", "")})
    return out

