def summarize_usage(events):
    """Sum token usage across requests.

    Each event carries a ``request_id`` and optional nonnegative integer
    ``input`` / ``output`` counts that are cumulative snapshots for that
    request.  For every request the maximum input and the maximum output are
    kept independently, then those per-request maxima are summed across
    requests.  A missing count is treated as 0; a negative count raises
    ValueError.  ``events`` is not mutated.
    """
    best = {}
    for ev in events:
        rid = ev["request_id"]
        inp = ev.get("input") or 0
        out = ev.get("output") or 0
        if inp < 0 or out < 0:
            raise ValueError("token counts must be nonnegative")
        prev = best.get(rid)
        if prev is None:
            best[rid] = (inp, out)
        else:
            best[rid] = (max(prev[0], inp), max(prev[1], out))
    return {'input': sum(v[0] for v in best.values()),
            'output': sum(v[1] for v in best.values())}

